
import type { PricingAmountsInput } from './PricingAmountsInput.js';
import type { SettlementAmountsInput } from './SettlementAmountsInput.js';

export type PackageStatusUpdateInput = { /** Controls buyer email handling. Omit or use send to send when recipient, template, and deduplication rules allow it. Use suppress when another system owns buyer messaging. */ "buyer_notification_behavior": "send" | "suppress"; /** Status update creation timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; /** Current package lifecycle state. Package states are the source used to derive shipment status. - `created`: The package record exists but has not been packed or handed off. - `packed`: The package is packed and awaiting carrier handoff. - `shipped`: The package was handed to the carrier. - `in_transit`: The carrier is moving the package through its network. - `out_for_delivery`: The package is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The package was returned toward or to its origin. - `voided`: The package was voided and will not continue through delivery. */ "current_status": "created" | "packed" | "shipped" | "in_transit" | "out_for_delivery" | "delivered" | "delivery_attempted" | "exception" | "returned" | "voided"; "fulfillment_id": string; /** Package transition timestamp. Format: date-time. */ "occurred_at"?: string | globalThis.Date; "order"?: (({ /** RFC3339 timestamp. Format: date-time. */ "created_at"?: string | globalThis.Date; "customer_id"?: string; "fulfillment_status"?: "not_fulfilled" | "partially_fulfilled" | "fulfilled" | "canceled" | "not_applicable" | "closed"; "order_id": string; "order_number"?: string; "payment_intent_ids"?: Array<string>; "payment_status": "unpaid" | "partially_paid" | "paid"; "pricing_amounts": PricingAmountsInput; "refund_status": "none" | "partially_refunded" | "refunded"; "settlement_amounts": SettlementAmountsInput; "status": "open" | "closed"; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: string | globalThis.Date; }) | (null)); "order_id": string; "package_id": string; "package_status_update_id": string; /** Current package lifecycle state. Package states are the source used to derive shipment status. - `created`: The package record exists but has not been packed or handed off. - `packed`: The package is packed and awaiting carrier handoff. - `shipped`: The package was handed to the carrier. - `in_transit`: The carrier is moving the package through its network. - `out_for_delivery`: The package is on its final delivery route. - `delivered`: The carrier reported successful delivery. - `delivery_attempted`: The carrier attempted delivery but did not complete it. Follow the carrier instructions before retrying delivery. - `exception`: A carrier exception is blocking normal progress. Resolve the carrier-reported issue. - `returned`: The package was returned toward or to its origin. - `voided`: The package was voided and will not continue through delivery. */ "previous_status": "created" | "packed" | "shipped" | "in_transit" | "out_for_delivery" | "delivered" | "delivery_attempted" | "exception" | "returned" | "voided"; /** The note supplied when this action was requested. */ "reason_message"?: string; "shipment_id": string; };
